        {"대지":"2대지: 보아스의 구속 (사랑의 기업 무름)", "내용":"기업 무를 자 보아스가 룻을 맞이함. 그리스도의 구속을 예표", "예화_적용":"우리도 누군가의 보아스가 될 수 있다. 사랑으로 이웃을 회복시키라"},
        {"대지":"3대지: 룻의 헌신 (당신의 하나님이 나의 하나님)", "내용":"모압 여인이 시어머니를 따라 이스라엘의 하나님을 선택", "예화_적용":"믿음은 결단이다. '주의 백성이 나의 백성, 주의 하나님이 나의 하나님'이라 고백하라"},
        {"대지":"결론", "내용":"라합과 룻의 이야기는 복음의 핵심이다. 자격이 아닌 믿음, 혈통이 아닌 은혜, 과거가 아닌 현재의 결단. 하나님은 이 기준으로 사람을 부르신다. 당신도 이 은혜의 족보에 이름을 올릴 수 있다", "예화_적용":"하나님은 당신의 과거가 아니라 당신의 믿음을 보신다"}
