        {"대지":"3대지: 솔로몬을 낳고 (은혜의 연속)", "내용":"죄의 결과 속에서도 평화(솔로몬)가 나오고 메시아 계보가 이어짐", "예화_적용":"하나님의 은혜는 우리의 실패보다 항상 더 크다"},
        {"대지":"결론", "내용":"다윗의 이야기는 인간의 나약함과 하나님의 강함을 동시에 보여준다. 위대한 왕도 넘어지지만, 위대한 하나님은 넘어진 자를 다시 일으키시고 약속을 이어가신다. 시편 51편의 다윗처럼 진심으로 회개할 때 회복은 시작된다", "예화_적용":"넘어진 것이 끝이 아니다. 다시 일어나라. 하나님의 은혜가 기다리고 있다"}
