        {"구절":"히 1:8", "연결점":"아들에 관하여는 영원무궁토록 있으리라", "구분":"신약"},
        {"구절":"계 11:15", "연결점":"세상 나라가 우리 주와 그 그리스도의 나라가 되리라", "구분":"신약"}
