    표6_설교자료: [
        {"대지":"제목", "내용":"바벨론 포로 - 심판 속의 소망", "예화_적용":"가장 어두운 밤에도 새벽은 준비되고 있다"},
        {"대지":"서론", "내용":"바벨론 포로는 이스라엘 역사 최대의 비극이다. 성전이 불타고, 왕이 끌려가고, 백성이 포로가 되었다. 그러나 마태는 이 비극 속에서도 메시아의 계보가 이어지고 있음을 보여준다. 심판 속에 소망이 숨겨져 있다", "예화_적용":"인생의 바벨론 포로 같은 순간에도 하나님의 계획은 진행 중이다"},
        {"대지":"1대지: 바벨론 이거 (죄의 결과)", "내용":"수백 년간 쌓인 우상숭배와 불순종의 결과가 포로라는 심판으로 나타남", "예화_적용":"죄는 반드시 결과를 낳는다. 그러나 그 결과가 영원한 것은 아니다"},
        {"대지":"2대지: 여고냐의 저주 (인간적 막다른 골목)", "내용":"왕위 계승이 저주받아 막힘. 인간적으로는 해결 불가능한 상황", "예화_적용":"인간의 한계가 하나님의 초자연적 해결(처녀 탄생)을 위한 자리를 만든다"},
        {"대지":"3대지: 형제들을 낳고 (공동체적 운명)", "내용":"한 사람의 포로가 아닌 온 민족의 포로. 죄의 영향은 공동체에 미침", "예화_적용":"나의 신앙은 나만의 것이 아니다. 공동체에 영향을 미친다"},
        {"대지":"결론", "내용":"바벨론 포로는 끝이 아니었다. 70년 후 귀환이 있었고, 500년 후 메시아가 오셨다. 하나님은 심판으로 끝내시는 분이 아니라 심판을 통해 더 큰 구원을 준비하시는 분이다", "예화_적용":"지금의 고난이 더 큰 은혜를 위한 준비일 수 있다"}
    ],
