        {"항목":"디아스포라 유대인", "내용":"이 시기 유대인들은 팔레스타인과 디아스포라로 흩어져 살며 율법 중심의 신앙을 유지. 회당과 랍비 문화가 발전", "목회적활용":"제도와 건물이 아닌 말씀 중심의 신앙 유지가 가능함을 보여줌"}
