        {"대지":"3대지: 조용한 시대의 의미 (때를 준비하심)", "내용":"메시아 탄생까지 수백 년간 조용히 이어진 계보. 하나님의 시간표", "예화_적용":"조용한 시간은 낭비가 아니라 준비이다"},
        {"대지":"결론", "내용":"우리 대부분의 삶은 아비훗과 엘리아김처럼 역사에 기록되지 않을 것이다. 그러나 하나님의 눈에는 매일 신실하게 사는 우리의 삶이 메시아 계보를 잇는 것만큼 귀하다. 평범한 오늘을 신실하게 살라", "예화_적용":"오늘의 평범한 신실함이 내일의 위대한 역사를 만든다"}
