        {"항목":"요셉의 법적 지위", "내용":"요셉은 예수의 생물학적 아버지가 아니지만 법적 아버지로서 다윗 왕가의 계보를 예수에게 연결. 유대 법에서 양자도 법적 상속권을 가짐", "목회적활용":"법적 관계를 통해서도 하나님의 약속이 성취됨을 보여줌"},
        {"항목":"그리스도라 칭하는", "내용":"'그리스도라 칭하는(레고메노스 크리스토스)'이라는 표현은 족보의 목적이 예수가 바로 그 약속된 메시아임을 증명하는 것임을 최종 선언", "목회적활용":"족보 전체가 이 한 사람을 향한 것임을 깨닫게 함"}
