        {"교리":"신인양성", "설명":"마리아에게서 나심(인성)과 그리스도(신성/직분)의 결합. 한 절에 예수의 인성과 신성이 동시에 선언됨", "관련구절":"요 1:14, 롬 1:3-4, 빌 2:6-8, 히 2:14"},
        {"교리":"족보의 완성", "설명":"아브라함에서 시작된 42대의 계보가 예수 그리스도에서 완성. 구약의 모든 약속이 이 한 사람에게 집중되어 성취됨", "관련구절":"마 1:1, 갈 3:16, 행 3:25, 눅 24:44"}
