        {"영어원문":"This is the centre to which all the lines of the genealogy converge: Jesus, who is called Christ.", "한국어번역":"이것이 족보의 모든 선이 수렴하는 중심이다: 그리스도라 칭하는 예수.", "핵심통찰":"42대의 족보가 향하는 유일한 중심점은 예수 그리스도"}
