        {"대지":"제목", "내용":"그리스도라 칭하는 예수가 나시니라 - 족보의 완성", "예화_적용":"2000년 역사가 향하던 단 한 사람"},
        {"대지":"서론", "내용":"마태복음 족보의 클라이맥스이다. 42대에 걸친 이름들이 모두 이 한 절을 향해 흘러왔다. 그런데 마태는 '요셉이 예수를 낳고'라 하지 않고 '마리아에게서 예수가 나시니라'고 쓴다. 이 문법의 변화 속에 처녀 탄생의 비밀이 있다", "예화_적용":"하나님은 세밀한 부분까지도 놓치지 않으신다"},
        {"대지":"1대지: 마리아의 남편 요셉 (법적 아버지)", "내용":"요셉은 생물학적 아버지가 아니지만 법적 아버지로서 다윗 왕가의 계보를 연결하는 중요한 역할", "예화_적용":"하나님은 보이지 않는 곳의 역할도 귀하게 여기신다"},
        {"대지":"2대지: 마리아에게서 나시니라 (처녀 탄생)", "내용":"능동태→수동태의 변화가 처녀 탄생을 암시. 인간의 힘이 아닌 하나님의 능력으로 오심", "예화_적용":"가장 위대한 사건은 인간이 아닌 하나님이 주도하심"},
        {"대지":"3대지: 그리스도라 칭하는 예수 (족보의 목적)", "내용":"42대의 족보가 향하는 유일한 목적: 이 분이 약속된 메시아 그리스도이시다", "예화_적용":"성경 전체가 가리키는 한 분, 예수 그리스도를 만나라"},
        {"대지":"결론", "내용":"족보의 마지막 이름은 예수 그리스도이다. 아브라함의 약속, 다윗의 언약, 선지자의 예언이 모두 이 한 분에게서 성취되었다. 이제 질문은 하나다. 당신은 이 예수를 당신의 그리스도로 영접했는가", "예화_적용":"족보를 읽는 것으로 끝나지 말고 족보가 가리키는 분을 만나라"}
