        {"대지":"2대지: 드러내지 아니하고 (자비를 선택한 사람)", "내용":"공개 고발 대신 비밀 이혼을 선택. 마리아의 명예와 생명을 보호하려는 배려", "예화_적용":"진짜 강한 사람은 벌줄 수 있는 권리를 포기하는 사람이다"},
        {"대지":"3대지: 가만히 끊고자 (조용한 의로움)", "내용":"소란 없이, 자기를 내세우지 않고, 조용히 문제를 해결하려 함", "예화_적용":"의로운 행동은 드러내야 하는 것이 아니라 조용히 실천하는 것이다"},
        {"대지":"결론", "내용":"요셉의 의로움은 우리에게 묻는다. 당신은 정의와 자비 중 하나만 선택하는가, 둘 다 추구하는가. 하나님은 '의와 인자가 만나고 공의와 평화가 입맞추는'(시 85:10) 분이시다. 요셉은 이 하나님의 성품을 닮은 사람이었다", "예화_적용":"하나님 닮은 의로움은 정의와 자비를 동시에 품는다"}
