        {"원어":"ῥηθέν (레덴)", "의미_문법":"말씀하신 바 - 동사 수동 분사. 말해진 것", "설교포인트":"하나님이 말씀하신 것은 반드시 이루어짐"},
        {"원어":"προφήτου (프로페투)", "의미_문법":"선지자 - 명사 남성 속격. 하나님의 대변자", "설교포인트":"선지자는 하나님의 말씀을 전달하는 도구"},
        {"원어":"κυρίου (퀴리우)", "의미_문법":"주 - 명사 남성 속격. 여호와 하나님", "설교포인트":"예언의 궁극적 저자는 선지자가 아닌 하나님"}
