        {"영어원문":"Which was spoken of the Lord by the prophet; the prophecy was God's word delivered through human instruments.", "한국어번역":"주께서 선지자로 하신 말씀, 예언은 인간 도구를 통해 전달된 하나님의 말씀이다.", "핵심통찰":"성경은 인간의 글이 아닌 하나님의 말씀"},
        {"영어원문":"Matthew's formula of fulfilment serves to prove that Jesus is the Christ of whom the prophets spoke.", "한국어번역":"마태의 성취 공식은 예수가 선지자들이 말한 바로 그 그리스도임을 증명하는 역할을 한다.", "핵심통찰":"구약 예언의 성취가 예수가 메시아이신 증거"}
