        {"대지":"2대지: 주께서 선지자로 하신 말씀 (성경의 영감)", "내용":"말씀의 원천은 '주'이시고 선지자는 전달자. 성경은 하나님이 저자이신 책", "예화_적용":"성경을 인간의 책으로 읽지 말고 하나님의 말씀으로 읽으라"},
        {"대지":"3대지: 이루려 하심이니 (반드시 성취되는 약속)", "내용":"예언과 성취 사이에 700년이 흘렀으나 약속은 정확히 이루어짐", "예화_적용":"하나님의 약속은 시간이 걸려도 반드시 이루어진다"},
        {"대지":"결론", "내용":"이 한 절은 우리에게 성경을 읽는 눈을 준다. 구약을 읽을 때 '이것이 예수님 안에서 어떻게 성취되었는가?'를 묻고, 신약을 읽을 때 '이것이 어떤 구약 약속의 성취인가?'를 묻는 것이다. 성경은 하나의 이야기이다", "예화_적용":"성경 66권을 하나의 이야기로 읽는 눈을 가지라"}
