        {"상황":"성탄의 의미를 되찾고 싶은 분", "성경원리":"성탄의 핵심은 선물이나 축제가 아니라 '하나님이 우리와 함께 오셨다'는 임마누엘의 선언", "실제적용":"이번 성탄에는 선물보다 임마누엘의 임재에 집중하라"}
