        {"새찬송가":"501", "통일찬송가":"350", "제목":"주의 뜻을 이루소서", "선정이유":"하나님의 뜻대로 행하는 삶"},
        {"새찬송가":"392", "통일찬송가":"296", "제목":"나의 갈 길 다 가도록", "선정이유":"끝까지 순종하는 결단"}
