        {"대지":"서론", "내용":"마태복음 1장의 마지막 절이다. 42대의 족보가 흘러오고, 성령의 잉태가 선언되고, 천사의 분부가 내려지고, 요셉의 순종이 이루어진 후 마침내 '이름을 예수라 하니라'로 끝맺는다. 구약 전체가 기다려온 그 이름이 마침내 세상에 선포되었다", "예화_적용":"2000년의 기다림이 이 한 이름으로 완성되었다"},
        {"대지":"1대지: 동침치 아니하더니 (절제의 순종)", "내용":"요셉은 하나님의 뜻을 위해 자신의 권리를 포기함. 처녀 탄생을 보증하는 절제", "예화_적용":"하나님의 뜻을 위해 자신을 내려놓을 수 있는가"},
        {"대지":"2대지: 낳으매 (성육신의 완성)", "내용":"하나님의 아들이 인간의 방식으로 세상에 오심. 하늘과 땅이 만나는 순간", "예화_적용":"하나님은 우리의 삶의 방식 속으로 들어오신다"},
        {"대지":"3대지: 이름을 예수라 하니라 (구원의 선포)", "내용":"천사의 분부대로 '여호와는 구원'이라는 이름이 아기에게 주어짐. 구원의 선포", "예화_적용":"예수라는 이름을 부를 때마다 '여호와는 구원하신다'를 고백하는 것"},
        {"대지":"결론", "내용":"마태복음 1장은 한 이름을 향해 달려왔다. 예수. 여호와는 구원. 이 이름이 세상에 주어졌다. 이것이 크리스마스이고, 이것이 복음이다. 당신은 이 이름을 부르고 있는가", "예화_적용":"예수의 이름을 부르는 것이 구원의 시작이다"}
