    표6_설교자료: [
        {"대지":"제목", "내용":"별을 보고 왕을 찾은 사람들", "예화_적용":"하나님은 각 사람에게 맞는 별을 보내신다"},
        {"대지":"서론", "내용":"동방박사들의 질문은 명확했다. '어디 계시뇨?' 그들은 메시아의 존재를 의심하지 않았고 오직 위치만 물었다. 이것이 참된 믿음의 자세", "예화_적용":"의심하는 자에게는 답이 멀고 확신하는 자에게는 길이 보인다"},
        {"대지":"1대지: 별을 본 눈 (하나님의 인도)", "내용":"같은 하늘을 봐도 별의 의미를 읽은 사람은 박사들뿐이었다. 영적 민감함의 중요성", "예화_적용":"하나님의 음성은 들으려는 귀에 들린다"},
        {"대지":"2대지: 경배의 목적 (예배자의 자세)", "내용":"박사들의 목적은 학문적 탐구가 아닌 경배였다. 모든 지식의 최종 목적지는 예배", "예화_적용":"성경 공부가 경배로 이어지지 않으면 반쪽짜리 신앙"},
        {"대지":"3대지: 왕으로 나신 이 (그리스도의 왕권)", "내용":"예수님은 왕이 된 것이 아니라 왕으로 태어나셨다. 본래적 왕권과 임명된 왕권의 차이", "예화_적용":"세상 권력은 얻고 잃지만 그리스도의 왕권은 영원하다"},
        {"대지":"결론", "내용":"동방박사들의 여정은 모든 믿음의 여정을 대표한다. 빛을 보고 따르며 끝내 왕 앞에 엎드리는 것. 우리도 삶의 별을 따라 그리스도께 나아가자", "예화_적용":"신앙은 여정이다. 멈추지 않으면 반드시 목적지에 도착한다"}
    ],
