        {"영어원문":"The brightest joys are those that arise from the removal of doubts and difficulties in our way to Christ.", "한국어번역":"가장 밝은 기쁨은 그리스도에게 가는 길에서 의심과 어려움이 제거될 때 일어나는 것이다.", "핵심통찰":"시련 후의 기쁨이 가장 깊은 기쁨"},
        {"영어원문":"When we see the star we should rejoice; for if Christ be ours, that is enough to make us happy.", "한국어번역":"별을 볼 때 기뻐해야 한다. 그리스도가 우리 것이면 그것만으로 행복하기에 충분하다.", "핵심통찰":"그리스도 한 분이면 충분한 기쁨"}
