        {"대지":"결론", "내용":"박사들의 세 가지 예물은 예수님의 정체성 전체를 고백한다. 왕이시며 하나님이시며 우리를 위해 죽으실 분. 우리도 보배합을 열어 가장 귀한 것을 드리는 경배자가 되자", "예화_적용":"내가 가진 가장 귀한 것을 주님께 드리는 것이 참된 예배"}
