        {"항목":"헤롯의 음모 좌절", "내용":"박사들이 돌아오지 않아 헤롯의 정보 수집 계획이 실패. 결국 무차별 학살로 이어짐(2:16)", "목회적활용":"악한 계획은 하나님의 개입으로 좌절됨"}
