        {"영어원문":"When God opens a way of escape, we must take it, and not tempt him by exposing ourselves to unnecessary danger.", "한국어번역":"하나님이 피할 길을 열어주시면 우리는 그 길을 취해야 하며 불필요한 위험에 자신을 노출시켜 하나님을 시험해서는 안 된다.", "핵심통찰":"하나님의 보호 방법을 거부하는 것은 교만"}
