        {"항목":"라헬의 상징", "내용":"라헬은 야곱의 사랑하는 아내이자 요셉과 베냐민의 어머니. 이스라엘 어머니의 대표적 상징", "목회적활용":"어머니의 슬픔으로 자녀의 비극을 표현하는 것은 가장 깊은 슬픔의 언어"},
        {"항목":"위로 거절", "내용":"'위로 받기를 거절했다'는 슬픔의 깊이를 표현. 인간적 위로가 닿지 않는 절대적 상실감", "목회적활용":"위로할 수 없는 슬픔 앞에서는 함께 있어주는 것이 최고의 위로"}
