        {"항목":"네 번째 꿈", "내용":"요셉에게 네 번째 나타난 꿈의 계시. 하나님의 인도가 일관되고 지속적임을 보여줌", "목회적활용":"하나님의 인도는 한 번으로 끝나지 않고 상황마다 새롭게 주어짐"},
        {"항목":"애굽 체류 기간", "내용":"약 2-3년간의 애굽 생활로 추정. 짧은 기간이지만 가족에게는 긴 피난 생활", "목회적활용":"기다림의 시간이 지나면 하나님이 새로운 길을 여심"}
