        {"교리":"하나님의 시간표", "설명":"'내가 네게 이르기까지'(2:13)라는 하나님의 약속이 헤롯의 죽음으로 성취됨. 하나님의 시간표는 정확", "관련구절":"전 3:1, 갈 4:4, 행 1:7"},
        {"교리":"새로운 시작", "설명":"헤롯의 죽음은 거룩한 가족에게 새로운 시작의 때. 하나님은 닫은 문 뒤에 새 문을 열어주심", "관련구절":"계 3:8, 사 43:19, 고후 5:17"}
