        {"항목":"요셉의 순종 패턴", "내용":"마태복음에서 요셉은 네 번의 꿈 지시에 모두 즉각 순종함(1:24, 2:14, 2:21, 2:22). 일관된 순종의 모범", "목회적활용":"신앙 생활은 한 번의 순종이 아닌 지속적 순종의 연속"},
        {"항목":"이스라엘 귀환", "내용":"예수 가족의 이스라엘 귀환은 이스라엘의 출애굽을 반복. 예수가 참 이스라엘로서 역사를 재현", "목회적활용":"하나님의 구속 역사는 반복과 완성의 패턴으로 진행됨"},
        {"항목":"정치적 상황", "내용":"헤롯 사후 그의 아들들이 영토를 분할 통치. 아켈라오(유대), 헤롯 안디바스(갈릴리), 빌립(이두래)", "목회적활용":"정치적 상황도 하나님의 섭리 안에 있음"}
