        {"영어원문":"Joseph obeyed promptly, as he had done before; good men are consistent in their obedience.", "한국어번역":"요셉은 이전과 같이 즉시 순종했다. 선한 사람은 순종에 있어 일관적이다.", "핵심통찰":"일관된 순종이 신앙의 성숙을 보여줌"},
        {"영어원문":"He came into the land of Israel; it was a figure of the greater return from the captivity of sin.", "한국어번역":"그가 이스라엘 땅으로 들어왔다. 이것은 죄의 포로됨에서의 더 큰 귀환의 그림이었다.", "핵심통찰":"물리적 귀환 속에 영적 귀환의 의미가 있음"},
        {"영어원문":"The child Jesus enters into the land of his inheritance; all the earth is his, but Israel was especially so.", "한국어번역":"아기 예수가 자기 기업의 땅에 들어오신다. 온 땅이 그의 것이나 이스라엘은 특별히 그러했다.", "핵심통찰":"메시아가 자기 백성의 땅에 오심"}
