        {"대지":"3대지: 이스라엘 땅으로 (약속의 땅 귀환)", "내용":"피난지를 떠나 약속의 땅으로 돌아옴. 하나님의 때가 오면 본래의 자리로 회복됨", "예화_적용":"어려운 시간이 지나면 하나님이 본래의 자리로 회복시켜 주신다"},
        {"대지":"결론", "내용":"요셉은 마태복음의 조용한 영웅이다. 그의 순종은 화려하지 않았지만 확실했다. 말 없는 순종, 즉각적 순종, 일관된 순종. 이것이 하나님이 찾으시는 신앙의 모습이다", "예화_적용":"화려한 신앙보다 조용한 순종이 하나님 보시기에 아름답다"}
