        {"원어":"κατῴκησεν (카토이케센)", "의미_문법":"거주하다/살다 - 동사 능동태 부정과거 3인칭 단수. 정착하다", "설교포인트":"만왕의 왕이 보잘것없는 마을에 정착하신 겸손"},
        {"원어":"Ναζωραῖος (나조라이오스)", "의미_문법":"나사렛 사람 - 형용사 남성 주격. 나사렛 출신", "설교포인트":"멸시의 칭호가 메시아의 정체성이 됨"},
        {"원어":"κληθήσεται (클레테세타이)", "의미_문법":"칭하리라/불리리라 - 동사 수동태 미래 3인칭 단수", "설교포인트":"예언의 성취가 뜻밖의 방식으로 이루어짐"}
