        {"구분":"다윗의 비천한 출신", "내용":"삼상 16:11 가장 작은 아들 다윗", "그리스도연결":"보잘것없는 곳에서 나오시는 만왕의 왕 그리스도"},
        {"구분":"기드온의 약함", "내용":"삿 6:15 므낫세 중 가장 약한 가문", "그리스도연결":"약한 곳을 택하여 강한 것을 이기시는 그리스도"}
