    표5_매튜헨리: [
        {"영어원문":"He came and dwelt in Nazareth; a place so mean that it was a proverb, 'Can any good thing come out of Nazareth?'", "한국어번역":"나사렛에 와서 거하셨다. 그곳은 '나사렛에서 무슨 선한 것이 나올 수 있겠느냐'가 속담이 될 정도로 비천한 곳이었다.", "핵심통찰":"메시아가 가장 비천한 곳을 선택하신 역설"},
        {"영어원문":"He shall be called a Nazarene; that is, he shall be despised and rejected of men.", "한국어번역":"나사렛 사람이라 칭하리라. 즉 그는 사람에게 멸시받고 버림받으실 것이다.", "핵심통찰":"멸시의 칭호가 구원자의 정체성이 됨"},
        {"영어원문":"Christ honoured Nazareth, not Nazareth Christ; he put dignity upon the place, not the place upon him.", "한국어번역":"그리스도가 나사렛을 영광스럽게 하셨지 나사렛이 그리스도를 영광스럽게 한 것이 아니다. 그가 그 곳에 존엄을 부여하셨다.", "핵심통찰":"그리스도는 어디에 계시든 그곳을 거룩하게 하심"}
    ],
