        {"대지":"서론", "내용":"마태복음 2장은 '나사렛 사람이라 칭하리라'로 끝난다. 이것은 멸시의 칭호였다. 그러나 마태는 이것이 예언의 성취라고 선언한다. 하나님은 세상의 멸시까지도 자신의 계획에 포함시키신다", "예화_적용":"세상이 무시하는 것 속에 하나님의 영광이 숨어 있다"},
        {"대지":"1대지: 나사렛이란 동네 (무명의 장소)", "내용":"구약에 한 번도 언급되지 않은 작은 마을. 세상의 기준으로 가치 없는 곳", "예화_적용":"하나님은 무명의 장소와 무명의 사람을 선택하신다"},
        {"대지":"2대지: 나사렛 사람 (멸시의 칭호)", "내용":"'나사렛 사람'은 비천한 출신을 뜻하는 멸시적 표현이었다", "예화_적용":"세상의 평가가 하나님의 평가와 다를 수 있다"},
        {"대지":"3대지: 예언의 성취 (하나님의 역설)", "내용":"멸시의 칭호가 예언의 성취가 되는 하나님의 역설적 방법", "예화_적용":"내가 부끄러워하는 것이 하나님의 계획 안에서는 영광이 될 수 있다"},
        {"대지":"결론", "내용":"예수님은 나사렛 사람이라 불리셨다. 세상은 이것을 멸시로 사용했지만 하나님은 예언의 성취로 사용하셨다. 당신의 비천한 시작, 보잘것없는 환경도 하나님의 손에서 영광의 도구가 된다", "예화_적용":"출신이 아닌 하나님의 부르심이 우리의 정체성을 결정한다"}
