        {"항목":"바리새인에 대한 요구", "내용":"바리새인의 율법 준수는 외적이었으나 요한은 내적 변화에서 오는 열매를 요구", "목회적활용":"형식적 순종이 아닌 마음의 변화에서 나오는 삶을 추구해야 함"},
        {"항목":"합당한의 의미", "내용":"악시온은 '저울에 달아 균형이 맞는'이라는 뜻. 회개에 걸맞은 무게감 있는 변화를 요구", "목회적활용":"입으로만이 아닌 삶으로 증명되는 회개"}
