        {"교리":"행위의 자리", "설명":"행위가 구원의 조건은 아니지만 구원의 증거. 열매가 나무의 정체를 보여줌", "관련구절":"엡 2:8-10, 약 2:18, 딛 3:8, 빌 2:12-13"},
        {"교리":"회개의 구체성", "설명":"막연한 회개가 아닌 '합당한' 열매를 요구. 회개는 구체적이어야 함", "관련구절":"눅 3:10-14, 행 26:20, 사 1:16-17"}
