        {"구분":"선악과", "내용":"창 3장 열매의 선택이 운명을 결정", "그리스도연결":"생명의 열매를 주시는 그리스도 (계 22:2)"},
        {"구분":"가나안의 열매", "내용":"민 13:23 가나안의 풍성한 포도 열매", "그리스도연결":"약속의 땅의 풍성함을 주시는 그리스도"}
