        {"대지":"결론", "내용":"나는 알곡인가 쭉정이인가? 이 질문이 오늘 우리에게 던져진다. 알곡은 무게감이 있다. 회개의 열매, 변화된 삶, 참된 믿음의 무게감. 쭉정이는 가볍다. 형식만의 신앙, 겉모습만의 경건. 오늘 나의 신앙에 무게감이 있는가", "예화_적용":"신앙의 무게감은 삶의 열매로 측정된다"}
