        {"원어":"ἀγαπητός (아가페토스)", "의미_문법":"사랑하는 - 형용사 남성 주격. 사랑 받는, 유일한", "설교포인트":"예수님은 아버지의 사랑을 받는 유일하신 아들"},
        {"원어":"υἱός (휘오스)", "의미_문법":"아들 - 명사 남성 주격. 아들", "설교포인트":"예수님의 하나님의 아들 됨이 공적으로 선언됨"},
        {"원어":"εὐδόκησα (유도케사)", "의미_문법":"기뻐하다 - 동사 능동태 부정과거 1인칭 단수. 기쁨을 느끼다", "설교포인트":"아버지가 아들에게서 기쁨을 찾으심"}
