        {"항목":"사랑하는 아들", "내용":"시 2:7의 '내 아들'과 사 42:1의 '나의 기뻐하는 자'의 결합. 왕적 메시아와 고난의 종 이미지가 합쳐짐", "목회적활용":"예수님은 왕이시면서 동시에 종이시며 사랑받는 아들"},
        {"항목":"공적 인증", "내용":"세례 장면에서 아버지의 공적 인증은 예수님의 메시아 사역에 대한 하나님의 승인", "목회적활용":"하나님의 인정이 사역의 가장 중요한 토대"}
