        {"대지":"서론", "내용":"40일 금식 후 극도로 배고프신 예수님께 마귀가 다가온다. '하나님의 아들이면 돌로 떡을 만들라.' 합리적으로 들리지만 이것은 치명적인 함정이었다", "예화_적용":"시험은 불합리한 것보다 합리적인 모습으로 올 때 더 위험하다"},
        {"대지":"1대지: 정체성 공격 (만일 아들이어든)", "내용":"마귀는 세례 때 하나님이 선언하신 '내 사랑하는 아들'이라는 정체성을 흔든다. 의심이 행동을 지배하게 만드는 전략", "예화_적용":"'정말 하나님이 너를 사랑하실까?' - 이것이 마귀의 오래된 질문이다"},
        {"대지":"2대지: 합법적 필요의 불법적 충족 (돌을 떡으로)", "내용":"배고플 때 먹는 것은 죄가 아니다. 그러나 하나님의 때와 방법을 기다리지 않고 자기 능력으로 해결하는 것이 문제", "예화_적용":"직장을 잃었을 때 불법적 방법으로 돈을 구하는 유혹에 빠지지 말라"},
        {"대지":"3대지: 하나님 신뢰의 시험 (아버지를 불신하라)", "내용":"이 시험의 핵심은 '하나님이 돌보시지 않으니 네가 알아서 하라'는 것이다. 하나님의 선하심을 의심하게 만든다", "예화_적용":"기도해도 응답이 없을 때 '내가 알아서 하겠다'는 태도가 바로 이 시험이다"},
        {"대지":"결론", "내용":"예수님은 돌을 떡으로 만들 능력이 있으셨지만 아버지의 뜻에 순종하셨다. 할 수 있지만 하지 않는 것, 이것이 진정한 승리이다", "예화_적용":"능력이 아니라 순종이 승리의 기준이다"}
