        {"항목":"말씀의 권위", "내용":"예수님은 기적이나 천사의 도움이 아닌 성경 말씀만으로 마귀에게 대응. 말씀의 충분성을 보여줌", "목회적활용":"성경 말씀 자체가 영적 전투의 완전한 무기"}
