        {"대지":"서론", "내용":"마귀는 광야에서 실패하자 장소를 바꾼다. 이번에는 성전 꼭대기이다. 가장 거룩한 장소에서 가장 위험한 시험이 시작된다. 마귀는 전략을 바꿀 줄 안다", "예화_적용":"교회 안에서 일어나는 시험이 세상의 시험보다 더 파괴적일 수 있다"},
        {"대지":"1대지: 거룩한 성의 시험 (장소의 착각)", "내용":"예루살렘 성전에 있으면 안전하다는 착각. 거룩한 장소에 있다고 시험에서 면제되지 않는다", "예화_적용":"교회에 다닌다고 자동으로 시험에서 보호되는 것이 아니다. 경성이 필요하다"},
        {"대지":"2대지: 꼭대기의 유혹 (높아짐의 위험)", "내용":"높은 곳에 세워지는 것은 교만의 시작이 될 수 있다. 영적 특권이 영적 교만이 되지 않도록 경계", "예화_적용":"직분을 맡은 후 교만해지는 성도들의 모습에서 이 시험을 본다"},
        {"대지":"3대지: 전략을 바꾸는 마귀 (끈질긴 공격)", "내용":"첫 시험 실패 후 마귀는 포기하지 않고 방식을 바꾼다. 물질에서 종교로 전환하는 교묘함", "예화_적용":"한 영역에서 승리했다고 방심하지 말라. 마귀는 다른 문으로 들어온다"},
        {"대지":"결론", "내용":"성전 꼭대기는 가장 거룩한 장소이지만 그곳에서도 시험은 온다. 중요한 것은 장소가 아니라 마음의 자세이다. 어디에 있든 말씀으로 무장해야 한다", "예화_적용":"매주 교회에 오지만 마음이 세상에 있다면 성전 꼭대기의 시험 한가운데 있는 것이다"}
