        {"교리":"순종적 신뢰", "설명":"참 믿음은 하나님을 떠보는 것이 아니라 조건 없이 신뢰하는 것. 결과를 확인하려는 것은 불신", "관련구절":"히 11:1, 롬 4:20-21, 잠 3:5-6, 시 37:5"}
