        {"영어원문":"To tempt God is to dare him, to challenge his power, to presume upon his promise.", "한국어번역":"하나님을 시험하는 것은 그분에게 도전하고 그분의 능력에 감히 맞서며 그분의 약속을 악용하는 것이다.", "핵심통찰":"하나님 시험의 본질은 불경건한 도전"},
        {"영어원문":"We must not presume upon the promise of God's protection, except we keep within the way of our duty.", "한국어번역":"우리의 본분의 길 안에 머무르지 않으면서 하나님의 보호 약속을 주장해서는 안 된다.", "핵심통찰":"약속은 순종의 길 안에서 유효하다"}
