        {"교리":"마귀의 한계", "설명":"마귀는 예수님의 말씀과 권위 앞에 물러갈 수밖에 없었다. 마귀의 권세는 제한적이며 하나님의 권위 아래 있음", "관련구절":"욥 1:12, 눅 22:31-32, 약 4:7, 요일 4:4"},
        {"교리":"그리스도의 완전한 승리", "설명":"세 시험 모두 승리함으로 첫 아담의 실패를 회복. 인류를 대표하여 완벽한 순종을 이룸", "관련구절":"롬 5:19, 고전 15:45, 히 4:15, 히 2:18"}
