    표6_설교자료: [
        {"대지":"제목", "내용":"마귀는 떠나고 천사가 왔다 - 시험 후의 은혜", "예화_적용":"광야 시험의 완벽한 승리와 하나님의 즉각적 위로"},
        {"대지":"서론", "내용":"마귀가 떠나고 천사가 온다. 이 짧은 문장에 하나님의 원리가 담겨 있다. 시험을 이기면 하나님의 위로가, 마귀가 떠나면 천사가 온다. 광야의 끝에는 반드시 은혜가 기다린다", "예화_적용":"폭풍 후에 무지개가 뜨듯 시험 후에 은혜가 온다"},
        {"대지":"1대지: 마귀가 떠남 (승리의 결과)", "내용":"말씀과 권위로 대적하니 마귀가 떠났다. 약 4:7의 약속이 실현된 것이다. 대적하면 반드시 물러간다", "예화_적용":"매번 유혹에 넘어지던 사람이 말씀을 무기로 단호히 거부할 때 유혹의 힘이 약해진다"},
        {"대지":"2대지: 천사가 수종듬 (위로와 회복)", "내용":"40일 금식과 세 번의 시험 후 예수님은 극도로 지쳐있었다. 천사의 수종은 육체적 회복이자 아버지의 인정", "예화_적용":"시험을 견디고 나면 하나님이 반드시 회복시켜 주신다. 고난 후에 더 큰 은혜가 온다"},
        {"대지":"3대지: 일시적 퇴각 (계속 깨어있음)", "내용":"눅 4:13에 따르면 마귀는 '얼마 동안' 떠난 것이다. 겟세마네에서 다시 온다. 한 번의 승리에 안주하지 말라", "예화_적용":"전쟁에서 한 전투의 승리가 전쟁의 종결이 아니듯 영적 전투는 지상에서 계속된다"},
        {"대지":"결론", "내용":"예수님의 광야 시험은 우리에게 세 가지를 가르친다. 첫째 말씀이 유일한 무기이다. 둘째 단호한 거부가 승리의 열쇠이다. 셋째 시험 후에 하나님의 위로가 반드시 온다. 이 확신을 갖고 시험을 견디자", "예화_적용":"히 12:11 '모든 징계가 당시에는 즐거워 보이지 않고 슬퍼 보이나 후에 그로 말미암아 연달한 자에게 의의 평강한 열매를 맺게 하느니라'"}
    ],
