        {"구절":"약 4:7", "연결점":"마귀를 대적하라 그리하면 너희를 피하리라", "구분":"신약"},
        {"구절":"히 1:14", "연결점":"모든 천사는 부리는 영으로 섬기게 하시는 것", "구분":"신약"},
        {"구절":"계 12:11", "연결점":"어린양의 피와 증거의 말씀으로 이기었으니", "구분":"신약"}
