        {"교리":"소외된 자를 향한 은혜", "설명":"종교적으로 경시당하던 갈릴리가 복음의 출발점이 됨. 하나님의 은혜는 소외된 곳에 먼저 닿음", "관련구절":"눅 4:18-19, 마 9:12, 고전 1:27-28, 약 2:5"},
        {"교리":"하나님의 역전", "설명":"가장 먼저 어두워진 곳이 가장 먼저 빛을 봄. 하나님은 절망의 순서를 은혜의 순서로 바꾸심", "관련구절":"마 19:30, 마 20:16, 눅 1:52-53, 눅 13:30"}
