        {"대지":"3대지: 하나님의 역전 (먼저 된 자와 나중 된 자)", "내용":"예루살렘이 아닌 갈릴리에서, 종교 지도자가 아닌 어부들에게서 복음이 시작됨", "예화_적용":"하나님의 방법은 세상의 서열을 뒤집는다. 나중 된 자가 먼저 되는 은혜의 역전"},
        {"대지":"결론", "내용":"당신이 소외되어 있다고 느끼는가? 경멸받고 있다고 느끼는가? 이방의 갈릴리가 복음의 시작점이 되었듯 당신의 자리가 하나님의 역사의 출발점이 될 수 있다", "예화_적용":"고전 1:27-28 '하나님이 세상의 약한 것들을 택하사 강한 것들을 부끄럽게 하려 하시며'"}
