        {"대지":"서론", "내용":"이사야의 예언이 이제 현실이 된다. 700년간 어둠 속에 앉아있던 백성에게 큰 빛이 비추었다. 그 빛은 촛불이 아니라 태양이었다. 예수 그리스도가 오신 것이다", "예화_적용":"깊은 동굴 속에서 한 줄기 빛을 발견한 것처럼 절망 속에 찾아온 희망"},
        {"대지":"1대지: 흑암에 앉은 백성 (어둠의 현실)", "내용":"어둠 속에 '앉아' 있었다는 것은 어둠에 안주했다는 뜻이다. 벗어나려 하지 않았고 벗어날 수도 없었다", "예화_적용":"죄의 어둠에 익숙해지면 그것이 정상이라 생각하게 된다. 빛을 만나야 어둠이 보인다"},
        {"대지":"2대지: 큰 빛을 보았고 (그리스도의 오심)", "내용":"이 빛은 작은 촛불이 아니라 '큰 빛'이다. 그리스도는 어둠의 일부를 밝히는 것이 아니라 전체를 밝히시는 분", "예화_적용":"예수님을 만나면 인생 전체가 바뀐다. 부분적 변화가 아닌 전면적 변화"},
        {"대지":"3대지: 사망의 그늘에 빛이 (생명의 소식)", "내용":"사망의 그늘 아래 있는 모든 인류에게 생명의 빛이 비추었다. 죽음을 이기시는 그리스도의 능력", "예화_적용":"죽음 앞에서도 소망이 있다. 부활의 빛이 사망의 어둠을 이기셨기 때문이다"},
        {"대지":"결론", "내용":"당신의 삶에 어둠이 있는가? 사망의 그늘이 드리워져 있는가? 큰 빛이신 예수 그리스도가 오셨다. 이 빛을 받아들이면 어떤 어둠도 물러간다", "예화_적용":"요 1:5 '빛이 어둠에 비취되 어둠이 깨닫지 못하더라' - 빛은 이미 비추고 있다"}
