        {"상황":"죽음의 공포에 사로잡힌 분", "성경원리":"사망의 그늘에 앉은 자들에게 빛이 비추었다. 그리스도는 죽음을 이기신 분이시다", "실제적용":"죽음은 끝이 아니라 새로운 시작이다. 부활의 소망 안에서 죽음의 공포를 이기라"},
        {"상황":"영적 암흑기를 지나는 분", "성경원리":"어둠이 가장 짙을 때 빛이 떠오른다. 새벽이 오기 직전이 가장 어둡다", "실제적용":"영적 암흑기는 새로운 은혜의 시작 직전일 수 있다. 기도를 멈추지 말라"}
