    표5_매튜헨리: [
        {"영어원문":"'Repent, for the kingdom of heaven is at hand.' This is the sum of the gospel, the same that John preached.", "한국어번역":"'회개하라 천국이 가까왔느니라.' 이것이 복음의 요약이며 요한이 전한 것과 동일하다.", "핵심통찰":"복음의 핵심은 시대를 초월하여 동일하다"},
        {"영어원문":"Repentance is the change of mind and heart, from sin to God.", "한국어번역":"회개는 죄에서 하나님에게로 마음과 생각을 바꾸는 것이다.", "핵심통찰":"회개는 감정이 아닌 방향 전환"},
        {"영어원문":"The kingdom of heaven is at hand — it is not merely future, but present in the person of Jesus.", "한국어번역":"천국이 가까왔다 - 단지 미래가 아니라 예수의 인격 안에 현재 임해 있다.", "핵심통찰":"천국은 예수와 함께 이미 시작되었다"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"회개하라 천국이 가까왔느니라 - 첫 번째 설교", "예화_적용":"예수님의 공생애 첫 선포 - 복음의 핵심"},
        {"대지":"서론", "내용":"예수님의 공생애 첫 마디가 '회개하라 천국이 가까왔느니라'이다. 이것은 복음의 전부를 요약한 한 문장이다. 회개(돌이킴)와 천국(하나님의 통치). 이 두 단어가 기독교의 핵심이다", "예화_적용":"모든 위대한 선언에는 핵심 메시지가 있다. 예수님의 핵심 메시지는 단 두 마디였다"},
        {"대지":"1대지: 회개하라 (방향 전환)", "내용":"회개는 눈물만이 아니다. 삶의 방향을 바꾸는 것이다. 죄에서 하나님에게로, 자기에서 그리스도에게로 돌아서는 결단", "예화_적용":"내비게이션이 '경로를 재탐색합니다'라고 할 때처럼 잘못된 길에서 돌아서야 한다"},
        {"대지":"2대지: 천국이 가까왔느니라 (하나님 나라의 도래)", "내용":"천국은 죽은 후에 가는 곳이 아니라 예수님과 함께 이미 시작된 하나님의 통치. 지금 여기서 경험할 수 있는 현실", "예화_적용":"천국은 하늘에만 있는 것이 아니다. 예수님을 왕으로 모시는 곳이 천국이다"},
        {"대지":"3대지: 이때부터 비로소 (새 시대의 시작)", "내용":"예수님의 선포는 새 시대의 시작을 알리는 것이었다. 율법의 시대에서 은혜의 시대로, 예비의 시대에서 성취의 시대로", "예화_적용":"인생에서 '이때부터'의 순간이 있다. 예수를 만나는 것이 가장 중요한 '이때부터'이다"},
        {"대지":"결론", "내용":"예수님의 첫 설교는 여전히 오늘 우리에게 유효하다. 회개하라 천국이 가까왔다. 지금 이 순간이 돌아설 때이다. 하나님의 나라가 당신 앞에 있다", "예화_적용":"행 17:30 '지금은 어디든지 사람에게 다 명하사 회개하라 하셨으니'"}
    ],
