        {"새찬송가":"305", "통일찬송가":"395", "제목":"나 같은 죄인 살리신", "선정이유":"회개와 구원의 은혜"},
        {"새찬송가":"268", "통일찬송가":"288", "제목":"왕 되신 주 앞에", "선정이유":"천국의 왕이신 주님께 경배"}
