        {"구절":"행 2:38", "연결점":"회개하여 각각 세례를 받고", "구분":"신약"},
        {"구절":"롬 14:17", "연결점":"하나님의 나라는 의와 평강과 성령 안에서 기쁨이라", "구분":"신약"}
