        {"원어":"ἁλιεῖς (할리에이스)", "의미_문법":"어부 - 명사 남성 복수 주격. 물고기 잡는 자", "설교포인트":"평범한 직업을 가진 사람을 부르시는 하나님"},
        {"원어":"ἀμφίβληστρον (암피블레스트론)", "의미_문법":"그물 - 명사 중성 대격. 던지는 투망", "설교포인트":"일상의 도구가 사역의 도구로 변함"}
