        {"대지":"서론", "내용":"예수님의 부르심은 두 가지였다. '나를 따라 오너라'(관계)와 '사람을 낚는 어부가 되게 하리라'(사명). 먼저 관계를 맺으시고 그 다음에 사명을 주신다. 이것이 제자도의 순서이다", "예화_적용":"사명 없는 관계는 공허하고 관계 없는 사명은 불가능하다"},
        {"대지":"1대지: 나를 따라오라 (관계의 초대)", "내용":"제자도의 첫걸음은 예수님과의 관계이다. 교리가 아니라 인격을 따르는 것. 삶을 함께 하는 동행", "예화_적용":"신앙은 규칙을 지키는 것이 아니라 예수님과 함께 사는 것이다"},
        {"대지":"2대지: 사람을 낚는 어부 (사명의 부여)", "내용":"어부의 기술과 경험이 영혼 구원의 사역에 사용됨. 하나님은 기존 경험을 낭비하지 않으신다", "예화_적용":"당신의 과거 경험과 현재 능력이 하나님 나라에서 쓰임받을 수 있다"},
        {"대지":"3대지: 되게 하리라 (변화의 약속)", "내용":"'내가 되게 하리라' - 변화의 주체는 예수님이시다. 자기 노력이 아니라 예수님의 능력으로 변화된다", "예화_적용":"무식한 어부가 세계 교회의 기둥이 된 것은 인간의 노력이 아니라 예수님의 변화시키는 능력"},
        {"대지":"결론", "내용":"예수님은 오늘도 우리를 부르신다. '나를 따르라.' 직업이 무엇이든, 능력이 어떠하든, 그분이 부르시면 우리는 사람을 낚는 어부가 될 수 있다. 변화시키시는 분은 예수님이시기 때문이다", "예화_적용":"빌 1:6 '너희 속에 착한 일을 시작하신 이가 그리스도 예수의 날까지 이루실 줄을 확신하노라'"}
