        {"원어":"ἀφέντες (아펜테스)", "의미_문법":"버려두다 - 분사 아오리스트. 떠나다/포기하다", "설교포인트":"부르심에 응답하려면 무언가를 내려놓아야 한다"},
        {"원어":"δίκτυα (딕튀아)", "의미_문법":"그물 - 명사 중성 복수 대격. 어부의 도구", "설교포인트":"생계 수단을 내려놓는 결단"},
        {"원어":"ἠκολούθησαν (에콜루데산)", "의미_문법":"따르다 - 동사 아오리스트. 뒤따르다/제자가 되다", "설교포인트":"따름은 일회적 결정이 아닌 지속적 삶"}
