        {"교리":"새로운 가족", "설명":"육적 가족을 떠나 예수님을 중심으로 한 새로운 영적 가족에 합류. 교회의 원형이 여기서 시작", "관련구절":"마 12:49-50, 막 10:29-30, 엡 2:19, 벧전 2:17"},
        {"교리":"즉각적 순종의 반복", "설명":"네 제자 모두 '곧' 따랐다는 반복은 참 제자도의 특징을 강조. 지체 없는 순종이 부르심의 본질적 응답", "관련구절":"시 119:60, 눅 9:59-62, 행 9:20, 갈 1:16"}
