        {"대지":"결론", "내용":"야고보와 요한이 버린 것은 배 한 척과 아버지와의 시간이었다. 그러나 얻은 것은 영원한 생명과 하나님 나라의 기둥이라는 사명이었다. 포기의 가치는 얻는 것으로 결정된다", "예화_적용":"마 19:29의 약속이 이 두 형제에게 문자적으로 이루어졌다"}
