        {"구분":"나아만의 치유", "내용":"수리아 장군 나아만의 문둥병 치유 (왕하 5:14)", "그리스도연결":"이방인까지 치유하시는 그리스도의 은혜"},
        {"구분":"히스기야의 치유", "내용":"죽을 병에서 치유받은 히스기야 왕 (왕하 20:5)", "그리스도연결":"어떤 질병도 고치시는 전능한 치유자 그리스도"}
