        {"항목":"새로운 시내산", "내용":"모세가 시내산에서 율법을 받아 전한 것과 대비. 예수님은 산에서 새 율법(은혜의 법)을 직접 선포. 모세보다 큰 입법자", "목회적활용":"산상수훈은 하나님 나라의 헌법이자 제자의 삶의 원칙"}
