        {"대지":"결론", "내용":"산상수훈의 서막이 올랐다. 역사상 가장 위대한 설교가 시작된다. 우리도 제자들처럼 예수님 앞에 나아가 이 말씀을 들어야 한다. 이것이 천국 시민의 삶의 원칙이기 때문이다", "예화_적용":"마 7:24 '이 내 말을 듣고 행하는 자는 반석 위에 집을 지은 지혜로운 사람'"}
