        {"대지":"서론", "내용":"두 번째 복도 역설적이다. '애통하는 자가 복이 있다.' 세상은 '웃는 자가 복이 있다'고 말하지만 예수님은 '우는 자가 복이 있다'고 선언하신다. 이 역설 속에 깊은 진리가 있다", "예화_적용":"웃을 줄 아는 사람도 중요하지만 울 줄 아는 사람이 더 깊은 사람이다"},
        {"대지":"1대지: 죄에 대한 애통 (회개의 깊이)", "내용":"애통의 첫째 의미는 자기 죄에 대한 깊은 슬픔이다. 가벼운 반성이 아닌 마음이 찢어지는 통회", "예화_적용":"다윗은 죄를 깨닫고 시편 51편을 썼다. 진정한 회개에는 눈물이 있다"},
        {"대지":"2대지: 세상에 대한 애통 (공감의 깊이)", "내용":"애통의 둘째 의미는 세상의 고통과 죄에 대한 슬픔이다. 다른 사람의 아픔을 내 아픔으로 느끼는 것", "예화_적용":"예레미야는 이스라엘의 죄를 보고 울었다. 세상의 아픔에 무감각하지 않는 것이 신앙인의 자세"},
        {"대지":"3대지: 위로의 약속 (하나님의 응답)", "내용":"하나님은 울고 있는 자를 지나치지 않으신다. 직접 위로하시고 눈물을 닦아주시겠다고 약속하셨다", "예화_적용":"시 56:8 '나의 눈물을 주의 병에 담으소서' - 하나님은 우리의 눈물 한 방울도 기억하신다"},
        {"대지":"결론", "내용":"울 줄 아는 사람이 위로받을 수 있다. 죄 앞에서, 세상의 아픔 앞에서, 하나님 앞에서 눈물을 흘릴 수 있다면 당신은 복 있는 사람이다. 위로의 하나님이 당신의 눈물을 닦아주실 것이다", "예화_적용":"시 126:5 '눈물을 흘리며 씨를 뿌리는 자는 기쁨으로 거두리로다'"}
