        {"구분":"다윗의 인내", "내용":"사울에게 쫓기면서도 보복하지 않은 다윗 (삼상 24:6)", "그리스도연결":"십자가 위에서도 용서하신 온유한 그리스도"},
        {"구분":"약속의 땅", "내용":"이스라엘이 기업으로 받은 가나안 땅", "그리스도연결":"온유한 자에게 새 하늘과 새 땅을 주시는 그리스도"}
