        {"새찬송가":"277", "통일찬송가":"186", "제목":"내 영혼이 은총 입어", "선정이유":"영혼이 정결해지는 은혜"},
        {"새찬송가":"384", "통일찬송가":"419", "제목":"내 주를 가까이 하려 함은", "선정이유":"청결한 마음으로 하나님을 가까이함"},
        {"새찬송가":"268", "통일찬송가":"288", "제목":"왕 되신 주 앞에", "선정이유":"하나님을 뵙는 최고의 복"}
