    표8_상담적용: [
        {"상황":"마음에 숨겨진 죄로 괴로운 분", "성경원리":"마음의 청결이 하나님을 만나는 조건이다. 숨긴 죄가 하나님과의 관계를 가로막는다", "실제적용":"숨겨진 죄를 하나님 앞에 고백하라. 요일 1:9 '우리가 만일 자백하면 저는 미쁘시고 의로우사 우리 죄를 사하시며 모든 불의에서 우리를 깨끗케 하실 것이요'"},
        {"상황":"겉으로는 신앙생활을 잘 하지만 속이 다른 분", "성경원리":"하나님은 겉이 아니라 마음을 보신다. 바리새인의 외적 청결은 하나님 앞에서 무의미했다", "실제적용":"겉과 속이 일치하는 삶을 추구하라. 사람에게 보이는 모습이 아니라 하나님 앞의 모습이 진짜 나이다"},
        {"상황":"하나님의 임재를 경험하지 못하는 분", "성경원리":"마음이 청결한 자가 하나님을 본다. 마음의 불순물이 하나님의 임재를 가릴 수 있다", "실제적용":"기도 중에 마음에 걸리는 것을 하나님 앞에 내려놓으라. 죄, 미움, 염려를 비우면 하나님의 임재가 채워진다"}
    ],
