        {"원어":"υἱοὶ θεοῦ (휘오이 데우)", "의미_문법":"하나님의 아들들 - 명사+명사 속격. 하나님의 자녀", "설교포인트":"화평케 하는 자가 하나님의 성품을 닮음"},
        {"원어":"κληθήσονται (클레데손타이)", "의미_문법":"일컬음을 받다 - 동사 미래 수동태. 불리다/칭해지다", "설교포인트":"하나님의 가문에 속한 자로 인정받음"}
