        {"항목":"화평케 하는 자", "내용":"에이레노포이오스는 능동적으로 평화를 '만드는' 자. 갈등 속에서 화해를 이끌고 분열을 하나로 만드는 적극적 역할", "목회적활용":"화평은 저절로 오지 않는다. 노력과 희생이 필요하다"},
        {"항목":"하나님의 아들", "내용":"'하나님의 아들'은 하나님의 성품을 닮은 자라는 의미. 화평케 하는 것은 하나님의 성품 중 하나(화해의 하나님)", "목회적활용":"화평을 이루는 것은 하나님을 닮아가는 가장 실제적 방법"}
