        {"교리":"하나님의 자녀됨", "설명":"하나님의 아들이라 '일컬음을 받음'은 하나님의 성품을 닮아 하나님의 가문에 속한 것으로 인정받는 것", "관련구절":"롬 8:14-17, 요 1:12, 갈 3:26, 요일 3:1"},
        {"교리":"능동적 평화", "설명":"에이레노포이오스(평화를 만드는 자)는 수동적이 아닌 능동적 행위. 갈등 속에서 화해를 이끌어내는 적극적 사역", "관련구절":"롬 12:18, 히 12:14, 약 3:18, 벧전 3:11"}
